// SPEC-03 step 4a: the ordered list of track assets (tracks.json order), generated by the editor TrackImporter.
// RaceLoop holds one reference to it; tracks are rebuilt at runtime from the data assets (decision D-25).
#nullable enable
using System.Collections.Generic;
using UnityEngine;

namespace DesktopDrift.Game
{
    public sealed class TrackCatalog : ScriptableObject
    {
        public List<TrackAsset> Tracks = new List<TrackAsset>();

        public TrackAsset? Find(string id)
        {
            foreach (TrackAsset t in Tracks)
                if (t != null && t.Id == id) return t;
            return null;
        }
    }
}
